import Foundation

/// The engine's text rules must give exactly the answers of the Python engine they were tuned in (freeflow-local).
/// Tests/Fixtures/engine-golden.json holds those answers on synthetic inputs (invented test cases and benchmark
/// sentences, no real dictation), generated by running the Python functions.
enum EngineTextTests {
    static func run() {
        let url = URL(fileURLWithPath: "Tests/Fixtures/engine-golden.json")
        guard let data = try? Data(contentsOf: url),
              let golden = try? JSONSerialization.jsonObject(with: data) as? [String: [[Any]]] else {
            fatalError("missing Tests/Fixtures/engine-golden.json (run tests from the repository root)")
        }
        func cases(_ key: String) -> [[Any]] { golden[key] ?? [] }

        for c in cases("ratio") {
            TestSupport.expectApproximatelyEqual(SequenceMatcher(c[0] as! String, c[1] as! String).ratio(), c[2] as! Double)
        }
        for c in cases("opcodes") {
            let ops = SequenceMatcher(c[0] as! [String], c[1] as! [String], autojunk: false).opcodes()
            let expected = (c[2] as! [[Any]]).map { "\($0[0]) \($0[1]) \($0[2]) \($0[3]) \($0[4])" }
            TestSupport.expectEqual(ops.map { "\($0.tag.rawValue) \($0.i1) \($0.i2) \($0.j1) \($0.j2)" }, expected)
        }
        for c in cases("sound") { TestSupport.expectEqual(ScreenWords.sound(c[0] as! String), c[1] as! String) }
        for c in cases("strength") { TestSupport.expectEqual(ScreenWords.strength(c[0] as! String), c[1] as! Int) }
        for c in cases("similarity") {
            TestSupport.expectApproximatelyEqual(ScreenWords.similarity(c[0] as! String, c[1] as! String), c[2] as! Double)
        }
        for c in cases("screen_words") {
            TestSupport.expectEqual(ScreenWords.screenWords(c[0] as! [String]), c[1] as! [String])
        }
        for c in cases("relevant") {
            TestSupport.expectEqual(ScreenWords.relevant(c[0] as! [String], transcript: c[1] as! String), c[2] as! [String])
        }
        for c in cases("strip_fillers") { TestSupport.expectEqual(CleanupText.stripFillers(c[0] as! String), c[1] as! String) }
        for c in cases("expanded") {
            let r = CleanupText.expandedTooMuch(raw: c[0] as! String, cleaned: c[1] as! String)
            TestSupport.expectEqual([r.warn, r.revert], c[2] as! [Bool])
        }
        for c in cases("restore") {
            let (text, n) = CleanupText.restoreUnsupportedTerms(raw: c[0] as! String, cleaned: c[1] as! String, terms: c[2] as! [String])
            let expected = c[3] as! [Any]
            TestSupport.expectEqual(n, expected[1] as! Int)
            if n > 0 { TestSupport.expectEqual(text, expected[0] as! String) }
        }
        for c in cases("compact") {
            TestSupport.expectEqual(CleanupText.compactSystemPrompt(c[0] as! String), c[1] as? String)
        }
        for c in cases("vocab_terms") {
            TestSupport.expectEqual(CleanupText.vocabularyTerms(c[0] as? String), c[1] as! [String])
        }
        testHintInsertion()
        testKeepSpokenWords()
        testAppPromptIsRecognised()
        testContextSummary()
    }

    /// The context request is answered from its metadata, without the model; other requests are not touched.
    private static func testContextSummary() {
        let request = "Analyze the screenshot plus metadata to infer current activity.App: Mail\nBundle ID: com.example.mail\nWindow: Re: Quarterly plan\nSelected text: None"
        TestSupport.expectEqual(CleanupText.contextSummary(request), "The user is dictating in Mail, in the window \"Re: Quarterly plan\".")
        TestSupport.expectEqual(CleanupText.contextSummary("App: Notes\nBundle ID: com.example.notes\nWindow: Notes\nSelected text: None"),
                                "The user is dictating in Notes.")
        TestSupport.expectEqual(CleanupText.contextSummary("App: Unknown\nBundle ID: Unknown\nWindow: Unknown"),
                                "The user is dictating in an unidentified app.")
        TestSupport.expect(CleanupText.contextSummary("Instructions: Clean up RAW_TRANSCRIPTION\nhello") == nil,
                           "a cleanup request is not a context request")
    }

    /// The cleanup model was trained on the compact prompt: TellWell's real default prompt (and with the vocabulary
    /// block the app appends) must be recognised and swapped. A mismatch here silently degrades every dictation.
    private static func testAppPromptIsRecognised() {
        let base = PostProcessingService.cleanupSystemPrompt(customSystemPrompt: "", outputLanguage: "", dictationLanguage: "")
        TestSupport.expect(CleanupText.compactSystemPrompt(base) == CleanupText.compactPrompt,
                           "the app's default cleanup prompt must map to the compact prompt")
        let withVocabulary = base + "\n\n" + """
The following vocabulary must be treated as high-priority terms while rewriting.
Use these spellings exactly in the output when relevant:
Grafana, Siddhant
"""
        let compact = CleanupText.compactSystemPrompt(withVocabulary)
        TestSupport.expect(compact?.hasPrefix(CleanupText.compactPrompt) == true, "vocabulary must not stop the swap")
        TestSupport.expectEqual(CleanupText.vocabularyTerms(compact), ["Grafana", "Siddhant"])
        TestSupport.expect(CleanupText.compactSystemPrompt("Rewrite this formally.") == nil, "custom prompts pass through")
    }

    private static func testHintInsertion() {
        let message = "Instructions: x\n\n\n\nRAW_TRANSCRIPTION:\n<<<RAW_TRANSCRIPTION\nask sid hunt\nRAW_TRANSCRIPTION"
        TestSupport.expectEqual(CleanupText.rawTranscript(message), "ask sid hunt")
        let withHints = CleanupText.addingHints(message, section: "SCREEN_WORDS: Siddhant\n")
        TestSupport.expect(withHints.contains("SCREEN_WORDS: Siddhant\n\nRAW_TRANSCRIPTION:"), "hints go before the transcript")
        TestSupport.expectEqual(CleanupText.addingHints(message, section: ""), message)
    }

    private static func testKeepSpokenWords() {
        TestSupport.expectEqual(CleanupText.keepSpokenWords(raw: "Yeah.", cleaned: "EMPTY"), "Yeah.")
        TestSupport.expectEqual(CleanupText.keepSpokenWords(raw: "Yeah.", cleaned: "\"EMPTY\""), "Yeah.")
        TestSupport.expectEqual(CleanupText.keepSpokenWords(raw: "", cleaned: "EMPTY"), "EMPTY")
        TestSupport.expectEqual(CleanupText.keepSpokenWords(raw: "Yeah.", cleaned: "Yeah."), "Yeah.")
    }
}
